// Threshold is this pass's own judgment call (health-scoring.workflow.json's formula caps at 100;
// 75 is 'clearly healthy, not just adequate'), not brief-specified - same flagged-judgment-call
// treatment as the scoring formula itself.
const SCORE_THRESHOLD = 75;

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.companies)) return json.data.companies;
  if (json && Array.isArray(json.companies)) return json.companies;
  return [];
}

const eligible = $input.all().flatMap(asArray).filter((c) => {
  // IRIDIUM TIER PROTECTION, built by construction (05 Section 9: 'untouched by automated
  // pipeline changes; requires human involvement + dedicated training first') - excluded here
  // rather than relying on every future caller remembering to check, per phase-4/README.md's own
  // 'worth building tier-check guards... so Iridium accounts are excluded by construction' note
  // from an earlier pass. Also excludes anyone already Iridium since there's no higher tier to
  // flag an upgrade toward.
  if (c.currentTier === 'Iridium') return false;
  return (c.engagementScore || 0) >= SCORE_THRESHOLD;
});

return eligible.map((c) => ({ json: c }));
